<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {Download,RefreshCw,Search,SearchX,ChevronLeft,ChevronRight} from 'lucide-vue-next'
import {api,cash,date,type Row} from '../lib'
import ListPager from './ListPager.vue'
import SortHeader from './SortHeader.vue'
import {rememberList,toggleSort} from '../listState'
import OrderDuration from './OrderDuration.vue'
import Modal from '../refund/Modal.vue'
import RefundOrderDetail from './RefundOrderDetail.vue'
const props=defineProps<{admin?:boolean;search?:string;canApply?:boolean;detailOnly?:boolean}>(),emit=defineEmits<{refresh:[];close:[]}>()
const items=ref<Row[]>([]),total=ref(0),page=ref(1),q=ref(''),status=ref(new URLSearchParams(props.search).get('status')||''),error=ref(''),busy=ref(false),detail=ref<Row>(),selected=ref(''),action=ref('resume'),note=ref(''),confirmed=ref(false),handling=ref(false)
const summary=ref<Row>(),feeState=ref(''),focus=ref(''),sort=ref('priority'),start=ref(''),end=ref(''),automatic=ref(true),refreshSeconds=ref(15)
const size=ref(10),sortBy=ref(''),sortDir=ref('desc')
rememberList(props.admin?'admin-refunds':'refunds',{page,size,sortBy,sortDir,q,status,feeState,focus,sort,start,end,automatic,refreshSeconds})
function order(field:string){toggleSort(field,sortBy,sortDir,page)}
const names:Row={queued:'排队中',processing:'办理中',verifying:'核实中',attention:'待跟进',succeeded:'服务已完成',failed:'办理失败',banned:'账号不可用',cancelled:'已取消'},fees:Row={frozen:'冻结中',settled:'已结算',released:'已释放'}
const endpoint=computed(()=>props.admin?'/admin/refund/orders':'/refund/orders'),pages=computed(()=>Math.max(1,Math.ceil(total.value/size.value)))
let timer:ReturnType<typeof setInterval>,active=true,request=0
async function load(quiet=false){if(props.detailOnly)return;if(!quiet)busy.value=true;const generation=++request;try{const d=await api(endpoint.value+'?'+new URLSearchParams({q:q.value,status:status.value,page:String(page.value),page_size:String(size.value),sort_by:sortBy.value,sort_dir:sortDir.value,...(props.admin?{fee_status:feeState.value,focus:focus.value,sort:sort.value,start:start.value,end:end.value}:{})}));if(active&&generation===request){items.value=d.items;total.value=d.total;if(page.value>pages.value){page.value=pages.value;return}summary.value=d.summary;error.value=''}}catch(e){if(active)error.value=(e as Error).message}finally{if(generation===request)busy.value=false}}
async function open(id:string){selected.value=id;detail.value=undefined;confirmed.value=false;note.value='';error.value='';try{const d=await api(endpoint.value+'/'+id);if(selected.value!==id)return;detail.value=d;action.value=d.recovery?.needs_review?'verify_only':'resume'}catch(e){error.value=(e as Error).message}}
async function cancel(){if(!detail.value)return;handling.value=true;try{await api('/refund/orders/'+detail.value.order.id+'/cancel','POST',{});await open(detail.value.order.id);await load();emit('refresh')}catch(e){error.value=(e as Error).message}finally{handling.value=false}}
async function resume(){handling.value=true;try{await api(endpoint.value+'/'+selected.value+'/resume','POST',{action:action.value,note:note.value});await open(selected.value);await load();emit('refresh')}catch(e){error.value=(e as Error).message}finally{handling.value=false}}
const hasFilters=computed(()=>!!(q.value||status.value||feeState.value||focus.value||start.value||end.value))
function reset(){q.value='';status.value='';feeState.value='';focus.value='';start.value='';end.value='';filter()}
function filter(){page.value=1;void load()}
function exportPage(){const rows=[['订单号','邮箱','状态','服务费（积分）','费用状态','提交时间'],...items.value.map(r=>[r.id,r.email,names[r.status],cash(r.fee),fees[r.fee_status],date(r.created_at)])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='代退订单.csv';a.click();URL.revokeObjectURL(url)}
watch([page,size,sortBy,sortDir],()=>void load())
watch(size,()=>{page.value=1})
watch(selected,(value,old)=>{if(props.detailOnly&&old&&!value)emit('close')})
function tick(){if(automatic.value&&document.visibilityState==='visible'&&!handling.value&&!busy.value){void load(true);if(selected.value&&detail.value&&['queued','processing','verifying','attention'].includes(detail.value.order.status))void refreshDetail()}}
watch(refreshSeconds,()=>{clearInterval(timer);timer=setInterval(tick,refreshSeconds.value*1000)})
onMounted(()=>{void load();const id=new URLSearchParams(props.search).get('order_id');if(id)void open(id);timer=setInterval(tick,refreshSeconds.value*1000)})
async function refreshDetail(){const id=selected.value;try{const d=await api(endpoint.value+'/'+id);if(active&&selected.value===id)detail.value=d}catch{}}
onUnmounted(()=>{active=false;clearInterval(timer)})
</script>
<template><template v-if="!detailOnly"><div class="page-heading"><div><span class="eyebrow">EVERY ORDER, IN ONE PLACE</span><h1>订单中心</h1><p>办理进度与费用状态分别记录，服务完成不代表退款到账。</p></div><a v-if="!admin&&canApply" href="#/refund" class="btn primary">办理代退</a></div><p v-if="error&&!selected" class="refund-error" role="alert">{{error}}</p><div v-if="admin&&summary" class="order-center-summary" aria-label="代退订单统计" :aria-busy="busy"><article v-for="item in [{key:'queued',label:'排队中'},{key:'running',label:'办理中'},{key:'attention',label:'待跟进'},{key:'succeeded',label:'已完成'},{key:'recovery_pending',label:'等待恢复'},{key:'recovery_alert',label:'占用告警'}]" :key="item.key" class="order-center-summary-card"><span>{{item.label}}</span><b>{{summary[item.key]||0}}</b></article></div><p v-if="admin&&summary?.recovery_alert" class="refund-error" role="alert">有 {{summary.recovery_alert}} 笔异常占用超过告警阈值，请核实服务进度。<button class="text-btn" @click="focus='recovery_alert';filter()">查看告警订单</button></p><section class="panel record-panel refund-orders">
 <div class="records-heading"><div><h2>全部订单</h2><p>办理进度与费用状态分别记录，查看详情可跟进完整进度。</p></div><div class="order-heading-actions"><button type="button" class="btn secondary" @click="exportPage" :disabled="!items.length"><Download :size="15"/>导出本页</button><button type="button" class="btn secondary" @click="load()" :disabled="busy"><RefreshCw :size="15" :class="{'records-spin':busy}"/>刷新</button></div></div>
 <form class="records-filters" @submit.prevent="filter">
  <label class="records-search"><Search :size="16"/><input v-model="q" type="search" placeholder="搜索订单号 / 账号邮箱" aria-label="搜索代退订单" maxlength="254"/></label>
  <label><select v-model="status" aria-label="订单状态" @change="filter"><option value="">全部办理状态</option><option v-if="admin" value="running">正在处理（含核实）</option><option v-for="(label,value) in names" :key="value" :value="value">{{label}}</option></select></label>
  <button class="btn secondary" :disabled="busy">查询</button><button v-if="hasFilters" type="button" class="text-btn records-reset" @click="reset">重置</button>
 </form>
 <form v-if="admin" class="records-filters refund-advanced" @submit.prevent="filter">
  <label><select v-model="feeState" aria-label="费用状态" @change="filter"><option value="">全部费用状态</option><option v-for="(label,key) in fees" :value="key" :key="key">{{label}}</option></select></label>
  <label><select v-model="focus" aria-label="关注事项" @change="filter"><option value="">全部关注事项</option><option value="long_wait">排队过久</option><option value="long_running">办理过久</option><option value="recovery_alert">异常占用告警</option></select></label>
  <label><select v-model="sort" aria-label="订单排序" @change="sortBy='';filter()"><option value="priority">优先处理异常</option><option value="newest">最新提交</option><option value="oldest">最早提交</option><option value="updated">最近更新</option></select></label>
  <div class="records-date-range"><label><span class="sr-only">开始日期</span><input type="date" v-model="start" :max="end||undefined" @change="filter"/></label><span>至</span><label><span class="sr-only">结束日期</span><input type="date" v-model="end" :min="start||undefined" @change="filter"/></label></div>
  <label class="refund-auto"><input type="checkbox" v-model="automatic"/>自动刷新</label><label><select v-model.number="refreshSeconds" aria-label="自动刷新间隔"><option v-for="n in [5,10,15,30,60]" :key="n" :value="n">{{n}} 秒</option></select></label>
 </form>
 <div class="records-count" role="status"><span><b>{{total}}</b> 条{{hasFilters?'匹配':''}}记录 <span class="records-scope">· 全部代退订单</span></span><span v-if="busy">正在刷新…</span></div>
 <div class="records-scroll" tabindex="0" aria-label="记录列表，可横向滚动"><table class="records-table refund-table"><thead><tr><SortHeader label="账号 / 订单号" field="email" :sort-by="sortBy" :sort-dir="sortDir" @sort="order"/><SortHeader v-if="admin" label="申请人" field="user_email" :sort-by="sortBy" :sort-dir="sortDir" @sort="order"/><SortHeader label="办理状态" field="status" :sort-by="sortBy" :sort-dir="sortDir" @sort="order"/><SortHeader label="服务费" field="fee" :sort-by="sortBy" :sort-dir="sortDir" @sort="order"/><SortHeader label="费用状态" field="fee_status" :sort-by="sortBy" :sort-dir="sortDir" @sort="order"/><th>总耗时</th><SortHeader label="提交时间" field="created_at" :sort-by="sortBy" :sort-dir="sortDir" @sort="order"/><th>操作</th></tr></thead><tbody>
  <tr v-for="row in items" :key="row.id"><td class="record-wide" data-label="账号 / 订单号"><div class="record-cell"><b>{{row.email}}</b><small class="mono">{{row.id}}</small></div></td><td v-if="admin" data-label="申请人"><div class="record-cell">{{row.user_email}}</div></td><td data-label="办理状态"><div class="record-cell"><span class="badge refund-status" :class="row.status">{{names[row.status]||row.status}}</span><small v-if="admin&&row.recovery_pending">等待恢复{{row.next_check_at?' · '+date(row.next_check_at):''}}</small><small v-if="admin&&row.recovery_alert" class="refund-error">异常占用告警</small></div></td><td data-label="服务费"><div class="record-cell"><b class="record-money">{{cash(row.fee)}} <em>积分</em></b></div></td><td data-label="费用状态"><div class="record-cell">{{fees[row.fee_status]}}</div></td><td data-label="总耗时"><OrderDuration :order="row"/></td><td data-label="提交时间"><div class="record-cell"><time>{{date(row.created_at)}}</time></div></td><td data-label="操作"><button class="text-btn record-detail" @click="open(row.id)">查看详情</button></td></tr>
 </tbody></table><div v-if="!items.length" class="records-empty"><SearchX :size="28"/><b>{{busy?'正在读取记录…':hasFilters?'没有符合条件的记录':'暂时没有记录'}}</b><p>{{hasFilters?'试试其他关键词，或清除筛选条件。':'新的业务记录会显示在这里。'}}</p><button v-if="hasFilters" class="text-btn" @click="reset">清除筛选</button></div></div>
 <ListPager v-model:page="page" v-model:size="size" :total="total" :loading="busy"/>
 </section>
</template>
<Modal v-if="selected" title="代退订单详情" wide :busy="handling" @close="selected='';detail=undefined"><p v-if="error" class="refund-error" role="alert">{{error}}</p><RefundOrderDetail v-if="detail" :detail="detail" :admin="admin"><template v-if="!admin&&detail.order.status==='queued'"><label class="confirm"><input v-model="confirmed" type="checkbox"/>确认取消排队申请并释放冻结服务费</label><button class="btn secondary" :disabled="!confirmed||handling" @click="cancel">取消申请</button></template><template v-if="admin"><form v-if="detail.recovery&&!['succeeded','failed','banned','cancelled','queued'].includes(detail.order.status)" class="recovery-form" @submit.prevent="resume"><h3>核实与恢复</h3><p class="muted small">根据已核实的结果选择处理方式，填写依据后执行。</p><select v-model="action" aria-label="处置方式"><option v-if="!detail.recovery.needs_review" value="resume">恢复办理</option><template v-else><option value="verify_only">只读核验结果</option><option value="confirm_accepted">有明确受理依据，恢复清理</option><option value="confirm_rejected">已确认未受理，重新处理</option></template><option v-if="detail.recovery.can_release" value="fail_cleaned">已核实清理，结束失败并释放</option></select><textarea v-model="note" minlength="5" maxlength="300" required rows="3" placeholder="填写核实依据或原因，不包含账号凭据"/><label class="confirm"><input v-model="confirmed" type="checkbox" required/>我已核实当前状态及操作依据</label><button class="btn primary" :disabled="!confirmed||handling||detail.recovery.running||(detail.recovery.needs_review&&action==='resume')">执行处置</button></form></template></RefundOrderDetail><p v-else-if="!error" role="status">正在读取订单详情…</p></Modal>
</template>
<style scoped>
.refund-advanced{padding-top:16px;border-top:1px solid var(--line)}.refund-advanced .refund-auto{flex-direction:row;align-items:center;gap:8px;flex:none;min-width:0;max-width:none;font-size:11px}.refund-auto input{width:16px;height:16px}.refund-table{min-width:900px}.refund-table th{width:auto}.refund-table th:first-child{width:27%}.refund-table .mono{overflow-wrap:anywhere}.refund-status{background:#f0f3f6;color:#5f7281;border:1px solid #dde4eb}.refund-status.succeeded{background:#eaf7ef;color:#18734d;border-color:#ccebd9}.refund-status.queued,.refund-status.processing{background:#edf4ff;color:#225daa;border-color:#d4e3fb}.refund-status.verifying,.refund-status.attention{background:#fff5df;color:#925b12;border-color:#f2deb0}.refund-status.failed,.refund-status.banned{background:#fff0f0;color:#b43c43;border-color:#f3d3d5}
.refund-error{color:#ad4138;font-size:12px}.confirm{display:flex;flex-direction:row;align-items:center;gap:10px;font-size:12px;margin:18px 0;line-height:1.8}.confirm input{width:auto}.recovery-form{display:grid;gap:14px;border-top:1px solid var(--line);padding-top:18px}
@media(max-width:760px){.refund-table{min-width:0}}
</style>
